"""Shot list (EDL) for video 02 – Dünkirchen 1940. Times in seconds (audio timeline, SRT verified).
type: V=archive video, P=photo full frame (Ken Burns), C=photo card over blurred bg, M=map scene, G=graphic/text card
src: media key (midia/commons/<key>.*) or map scene id or video key with in-point (V02@mm:ss)
txt: on-screen text items  (kind:text)  kinds: word (center black box), lt (lower third name|role), date, loc (top-left title),
     stamp, quote, list, counter, chapter, clock
sfx: whoosh, type, stamp, tick, hit
"""
import json, os

S = []
def shot(t0, t1, typ, src, desc, txt=None, sfx=None, move=None):
    S.append(dict(t0=t0, t1=t1, type=typ, src=src, desc=desc, txt=txt or [], sfx=sfx or [], move=move or ''))

